const upsertEpisodeListing = `-- name: UpsertEpisodeListing :one
INSERT INTO episode_listings (
        episode_id,
        price,
        reading_period_hours,
        status,
        scheduled_at,
        published_at,
        tenant_id
    )
VALUES ($1, $2, $3, $4, $5, $6, $7) ON CONFLICT (episode_id) DO
UPDATE
SET price = EXCLUDED.price,
    reading_period_hours = EXCLUDED.reading_period_hours,
    status = EXCLUDED.status,
    scheduled_at = EXCLUDED.scheduled_at,
    published_at = EXCLUDED.published_at
RETURNING episode_id, price, reading_period_hours, status, scheduled_at, published_at, tenant_id
`

type UpsertEpisodeListingParams struct {
	EpisodeID          uuid.UUID     `json:"episode_id"`
	Price              int32         `json:"price"`
	ReadingPeriodHours sql.NullInt32 `json:"reading_period_hours"`
	Status             string        `json:"status"`
	ScheduledAt        sql.NullTime  `json:"scheduled_at"`
	PublishedAt        sql.NullTime  `json:"published_at"`
	TenantID           uuid.UUID     `json:"tenant_id"`
}

func (q *Queries) UpsertEpisodeListing(ctx context.Context, arg UpsertEpisodeListingParams) (EpisodeListing, error) {
	row := q.db.QueryRowContext(ctx, upsertEpisodeListing,
		arg.EpisodeID,
		arg.Price,
		arg.ReadingPeriodHours,
		arg.Status,
		arg.ScheduledAt,
		arg.PublishedAt,
		arg.TenantID,
	)
	var i EpisodeListing
	err := row.Scan(
		&i.EpisodeID,
		&i.Price,
		&i.ReadingPeriodHours,
		&i.Status,
		&i.ScheduledAt,
		&i.PublishedAt,
		&i.TenantID,
	)
	return i, err
}
